create schema if not exists heygro;
set search_path to heygro;
create table if not exists users(id uuid primary key default gen_random_uuid(), x_user_id text unique, x_username text, x_avatar text, wallet_address text unique, telegram_id text unique, created_at timestamptz default now(), banned bool default false);
create table if not exists user_identities(user_id uuid references users(id), kind text, subject text, primary key(kind, subject));
create table if not exists sessions(id text primary key, user_id uuid references users(id), expires_at timestamptz);
create table if not exists custodial_wallets(id uuid primary key default gen_random_uuid(), owner_key text unique, pubkey text unique, ciphertext bytea, iv bytea, wrapped_dek bytea, dek_iv bytea, key_version int default 1, created_at timestamptz default now());
create table if not exists connector_keys(id uuid primary key default gen_random_uuid(), user_id uuid references users(id), token_hash text unique, created_at timestamptz default now(), revoked_at timestamptz);
create table if not exists oauth_clients(client_id text primary key, redirect_uris jsonb, client_name text, metadata_url text, created_at timestamptz default now());
create table if not exists oauth_codes(code_hash text primary key, client_id text, user_id uuid, redirect_uri text, code_challenge text, resource text, scope text, expires_at timestamptz, used_at timestamptz);
create table if not exists oauth_tokens(token_hash text primary key, kind text, client_id text, user_id uuid, resource text, scope text, expires_at timestamptz, revoked_at timestamptz);
create table if not exists oauth_pending(id text primary key, params jsonb, expires_at timestamptz);
create table if not exists drafts(id uuid primary key default gen_random_uuid(), owner_key text not null, status text not null default 'open', name text, ticker text, logo_cid text, description text, website text, x text, telegram text, socials_done bool default false, pair_mint text, pair_symbol text, creator_fee_bps int, creator_fee_done bool default false, fee_mode text, fee_x_handle text, fee_x_user_id text, fee_wallet text, upload_token_hash text, upload_expires_at timestamptz, error text, created_at timestamptz default now(), updated_at timestamptz default now());
create index if not exists drafts_owner on drafts(owner_key, status);
create table if not exists launches(id uuid primary key default gen_random_uuid(), draft_id uuid unique, owner_key text, mint text unique, create_sig text, split_sig text, split_status text, split_attempts int default 0, metadata_cid text, creator text, recipient text, quote_mint text, is_holder_reward bool, creator_fee_bps int, name text, ticker text, logo_cid text, fee_label text, launched_at timestamptz default now());
create table if not exists launch_counters(key text, day_utc date, count int default 0, primary key(key, day_utc));
create table if not exists pairs(mint text primary key, symbol text, name text, decimals int, source text, token_program text, graduation text, custom_fee_allowed bool, synced_at timestamptz default now());
create table if not exists wallet_ops(id uuid primary key default gen_random_uuid(), owner_key text, kind text, args_hash text, preview jsonb, status text, sig text, error text, created_at timestamptz default now());
create table if not exists pending_actions(id text primary key, owner_key text, tool text, args jsonb, args_hash text, summary text, expires_at timestamptz, used_at timestamptz);
create table if not exists siws_nonces(nonce text primary key, expires_at timestamptz);
create table if not exists telegram_links(token text primary key, telegram_id text, expires_at timestamptz, used_at timestamptz);
create table if not exists user_settings(user_id uuid primary key, model text);
create table if not exists x_handles(handle text primary key, x_user_id text, resolved_at timestamptz default now());
create table if not exists audit_log(id bigserial primary key, actor text, action text, detail jsonb, ts timestamptz default now());
create table if not exists candles(mint text, interval text, time bigint, open numeric, high numeric, low numeric, close numeric, volume numeric, buy_volume numeric, primary key(mint, interval, time));
-- templates, volume bots, airdrops, trade index
create table if not exists templates(id text primary key, name text not null, ticker text not null, description text, logo_cid text, pair text default 'SOL', theme text, sort int default 0, created_at timestamptz default now());
create table if not exists bot_orders(id uuid primary key default gen_random_uuid(), owner_key text not null, mint text not null, kind text not null, package text not null, price_lamports bigint, target_volume_lamports bigint, done_volume_lamports bigint default 0, trades int default 0, max_trades int, status text default 'queued', pay_sig text, error text, created_at timestamptz default now(), updated_at timestamptz default now());
create index if not exists bot_orders_status on bot_orders(status);
create table if not exists bot_txs(id bigserial primary key, order_id uuid, mint text, side text, lamports bigint, wallet text, sig text, ok bool, error text, ts timestamptz default now());
create index if not exists bot_txs_ts on bot_txs(ts desc);
create table if not exists bot_wallets(pubkey text primary key, order_id uuid, enc_secret text, created_at timestamptz default now());
create table if not exists curve_trades(sig text primary key, mint text, owner_key text, side text, lamports bigint, trader text, ts timestamptz);
create index if not exists curve_trades_mint on curve_trades(mint, ts desc);
create table if not exists airdrops(id bigserial primary key, period text not null, period_key text not null, rank int not null, owner_key text, wallet text, volume_lamports bigint, amount_lamports bigint, sig text, status text default 'pending', error text, ts timestamptz default now(), unique(period, period_key, rank));
create table if not exists index_cursor(mint text primary key, last_sig text, updated_at timestamptz default now());
alter table sessions add column if not exists created_at timestamptz default now();
alter table curve_trades add column if not exists tokens numeric; alter table curve_trades add column if not exists price numeric;
create table if not exists tg_wallet_prefs(telegram_id text primary key, mode text not null default 'custodial', payout_address text, updated_at timestamptz default now());
-- agents, claim codes, community, A2A, user LLM keys
create table if not exists agents(id uuid primary key default gen_random_uuid(), handle text unique not null, name text not null, bio text, avatar_url text, owner_user_id uuid, wallet_mode text not null, wallet_address text, payout_address text, api_key_hash text unique not null, verify_code text unique not null, x_post_url text, x_handle text, verify_status text not null default 'none', autotrade bool default false, created_at timestamptz default now());
create table if not exists claim_codes(id bigserial primary key, mint text unique not null, payout_wallet text not null, code_hash text unique not null, created_at timestamptz default now(), last_used_at timestamptz, unique(mint, payout_wallet));
create table if not exists fee_claims(id bigserial primary key, mint text, wallet text, lamports bigint, sig text unique, via text, ts timestamptz default now());
create index if not exists fee_claims_wallet on fee_claims(wallet);
create table if not exists posts(id bigserial primary key, author_key text not null, body text not null default '', reply_to bigint, repost_of bigint, kind text not null default 'post', call jsonb, created_at timestamptz default now());
create index if not exists posts_created on posts(created_at desc); create index if not exists posts_author on posts(author_key, created_at desc); create index if not exists posts_reply on posts(reply_to);
create unique index if not exists posts_one_repost on posts(author_key, repost_of) where repost_of is not null and body = '';
create table if not exists likes(post_id bigint, actor_key text, ts timestamptz default now(), primary key(post_id, actor_key));
create table if not exists follows(follower_key text, followee_key text, ts timestamptz default now(), primary key(follower_key, followee_key));
create table if not exists a2a_subs(subscriber_key text, agent_id uuid, autotrade bool default false, max_lamports bigint default 0, daily_lamports bigint default 0, ts timestamptz default now(), primary key(subscriber_key, agent_id));
create table if not exists a2a_exec(id bigserial primary key, post_id bigint, subscriber_key text, side text, lamports bigint, sig text, ok bool, error text, ts timestamptz default now(), unique(post_id, subscriber_key));
create table if not exists llm_keys(owner_key text primary key, provider text not null, model text, ciphertext bytea, iv bytea, wrapped_dek bytea, dek_iv bytea, updated_at timestamptz default now());
